        private static readonly DirectorySearchEngine.SearchIndex Index = DirectorySearchEngine.BuildIndex(
            Listings,
            new SearchSignals
            {
                ByEntryId = Reviews,
                SiteMeanRating = 4.22,
                NowUtc = new DateTime(2026, 11, 13, 0, 0, 0, DateTimeKind.Utc),
            });

        /// <summary>Navigational searches: the business searched for is first.</summary>
        [Theory]
        [InlineData("trocador", "Trocador")]
        [InlineData("goymail", "GoyMail")]
        [InlineData("bitania", "Bitania")]
        [InlineData("baltex", "Baltex")]
        [InlineData("xmr.cards", "XMR.CARDS")]
        [InlineData("quickex", "QuickEx")]
        [InlineData("coinsbee", "Coinsbee")]
        [InlineData("mullvad", "Mullvad")]
        [InlineData("kraken", "Kraken")]
        [InlineData("ghostswap", "GhostSwap")]
        [InlineData("solvocard", "SolvoCard.com")]
        [InlineData("0trace", "0trace")]
        [InlineData("trevoid", "Trêvoid Crypto Swaps")]
        [InlineData("silent link", "Silent Link")]
        [InlineData("pablo", "Pablo.Cash")]
        [InlineData("goblin", "Goblin Card")]
        [InlineData("xmr2cex", "xmr2cex")]
        [InlineData("sageswap", "SageSwap")]
        public void BusinessName_IsFirst(string query, string expected)
        {
            var results = Search(query);

            Assert.NotEmpty(results);
            Assert.Equal(expected, results[0].Name);
        }

        /// <summary>Generic searches: results exist and the first one is that kind of listing.</summary>
        [Theory]
        [InlineData("vps", "VPS Hosting|Dedicated")]
        [InlineData("sms", "SMS Verification")]
        [InlineData("esim", "eSIMs")]
        [InlineData("e-sim", "eSIMs")]
        [InlineData("e sim", "eSIMs")]
        [InlineData("vpn", "VPNs")]
        [InlineData("gift card", "Gift Cards")]
        [InlineData("gift cards", "Gift Cards")]
        [InlineData("giftcard", "Gift Cards")]
        [InlineData("gambling", "Gambling")]
        [InlineData("casino", "Gambling")]
        [InlineData("email", "Email Providers")]
        [InlineData("mail", "Email Providers")]
        [InlineData("buy monero", "Exchanges")]
        [InlineData("buy crypto", "Exchanges")]
        [InlineData("credit card", "Cards")]
        [InlineData("simcard", "eSIMs")]
        [InlineData("wallet", "Wallets")]
        [InlineData("domain", "Domains")]
        [InlineData("ai", "AI Services")]
        [InlineData("porn", "Pornography")]
        [InlineData("swap", "Exchanges")]
        [InlineData("dex", "Exchanges")]
        [InlineData("hosting", "Web Hosting")]
        [InlineData("prepaid", "Cards")]
        [InlineData("p2p", "Peer-to-Peer")]
        [InlineData("storage", "Storage")]
        [InlineData("gpu", "GPU")]
        public void GenericSearch_FirstResultIsThatKindOfListing(string query, string expectedCategoryPattern)
        {
            var results = Search(query);

            Assert.NotEmpty(results);
            var first = results[0];
            var where = $"{first.SubCategory?.Category?.Name}/{first.SubCategory?.Name}";
            Assert.Matches(new Regex(expectedCategoryPattern), where);
            Assert.NotEqual(DirectoryStatus.Scam, first.DirectoryStatus);
            Assert.NotEqual(DirectoryStatus.Questionable, first.DirectoryStatus);
        }

        [Fact]
        public void GenericSearch_NeverShowsScamListings()
        {
            foreach (var q in new[] { "vps", "sms", "esim", "vpn", "gift card", "swap", "email", "dex" })
            {
                Assert.DoesNotContain(Search(q), e => e.DirectoryStatus == DirectoryStatus.Scam);
            }
        }

        private static List<DirectoryEntry> Search(string q) => DirectorySearchEngine.Rank(Index, q);

        private static DirectoryEntry R(int id, string name, string subcategory, string category, int status, int? kyc, string link, string? description, string tags, int reviews, double rating)
        {
            if (reviews > 0)
            {
                Reviews[id] = new SearchListingSignals { ReviewCount = reviews, AverageRating = rating, LastReviewUtc = new DateTime(2026, 10, 1, 0, 0, 0, DateTimeKind.Utc) };
            }

            return new DirectoryEntry
            {
                DirectoryEntryId = id,
                Name = name,
                DirectoryEntryKey = $"k{id}",
                Link = link,
                Description = description,
                DirectoryStatus = (DirectoryStatus)status,
                KycPolicy = kyc.HasValue ? (KycPolicy)kyc.Value : null,
                SubCategory = new Subcategory
                {
                    Name = subcategory,
                    SubCategoryKey = subcategory.ToLowerInvariant(),
                    Category = new Category { Name = category, CategoryKey = category.ToLowerInvariant() },
                },
                EntryTags = tags.Split('|', StringSplitOptions.RemoveEmptyEntries)
                    .Select(t => new DirectoryEntryTag { DirectoryEntryId = id, Tag = new Tag { Name = t, Key = t.ToLowerInvariant() } })
                    .ToList(),
            };
        }
